class ConfCargospagosporresultados extends BaseConfCargospagosporresultados
{

    /**
     * Obtener un listado de los datos de los tipos de pago.
     *
     * @param int $inicio Inicio de la busqueda.
     * @param int $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los tipos de pago.obtenerConfpagosporresultados
     */

    public function getByid($idcargospagoporresultado)
    {
        return Doctrine::getTable('ConfCargospagosporresultados')->find($idcargospagoporresultado);
    }

    public static function ObtenerCargosapagosporresultados($idpagoporresultado,$idestructura, $inicio = 0, $limite = 10)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        $sqlData = "select cpr.*,na.denominacion as area
						   from mod_nomina.conf_cargospagoporresultado cpr
									inner join mod_nomina.nom_areascargos nac on (nac.idcargo = cpr.idcargo and nac.idarea = cpr.idarea)
									inner join mod_nomina.nom_areas na on (na.idarea = nac.idarea)
									where cpr.idpagoporresultado = ? and na.idestructura = ?;";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();

        $arrData = $conn->fetchAll($sqlData, array($idpagoporresultado, $idestructura));
        return $arrData;
    }

    public static function ObtenercargosdadoIdcargoyIdpago($idcargo, $idpagoporresultado,$idarea)
    {
        return Doctrine_Query::create()
            ->select('cpr.*,')
            ->from('ConfCargospagosporresultados cpr')
            ->where('cpr.idpagoporresultado = ? and cpr.idcargo = ? and cpr.idarea = ? ', array($idpagoporresultado, $idcargo, $idarea))
            ->fetchArray();

    }

    public static function ObtenerCargosporareas($idarea,$idestructura)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        $sqlData = "select nac.idcargo as idcargo,nac.idarea as idarea,na.denominacion as area
                    from mod_nomina.nom_areas na
                    inner join mod_nomina.nom_areascargos nac on (nac.idarea = na.idarea)
                    where nac.idarea = ? and na.idestructura = ?;";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();

        $arrData = $conn->fetchAll($sqlData, array($idarea, $idestructura));
        return $arrData;
    }

    public static function ObtenerCargosporareasPagoResultados($idarea,$idestructura, $idpagoporresultado)
    {
        //Devolviendo el listado de tipos de pago en forma de arreglo.
        $sqlData = "select nac.*,na.denominacion as area
                    from mod_nomina.nom_areas na
                    inner join mod_nomina.nom_areascargos nac on (nac.idarea = na.idarea)
                    left join mod_nomina.conf_cargospagoporresultado ccpr on (ccpr.idcargo = nac.idcargo and nac.idarea = ccpr.idarea)
                    where nac.idarea = ? and na.idestructura = ?;";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();//print_r(array($idarea, $idestructura));die;

        $arrData = $conn->fetchAll($sqlData, array($idarea, $idestructura));
        return $arrData;
    }
}
